// OMP native event-to-trace adapter (T04, spec 2026-08-31-2018-harness-followup-audit).
// Generated by scripts/export-to-omp.mjs; installed at
// <agentHome>/extensions/harness-omp-trace.ts through the exporter/install/check
// tooling. Do not hand-edit the installed copy.
//
// Subscribes to the native OMP lifecycle event bus (pi.on) and persists
// T01-envelope records through the shared contract module
// (<agentHome>/scripts/harness-trace.mjs): the runtime spine - session, run (one
// per agent turn), and model (usage/cost/context per run) records.
//
// Boundaries (never crossed):
//  - No session JSONL, history/agent databases, statusline, or manual commands
//    are read or mislabeled as tracing; only native lifecycle events are consumed.
//  - No prompt, assistant message, or tool bodies are persisted.
//  - Tool payload capture belongs to ai-memory.
//  - Missing model usage/cost/context are persisted as explicit unavailable by
//    the contract module; zeros are only recorded when the runtime explicitly
//    supplies them.
//  - Lifecycle records (phase/gate/finding/review/judge/handoff) are appended by
//    their owning harness commands; until they emit, --verify surfaces any
//    correlation gaps instead of inventing joins.
import os from "node:os"
import path from "node:path"
import { fileURLToPath, pathToFileURL } from "node:url"

interface TraceModule {
  newId(prefix: string): string
  appendEventAsync(root: string, json: string): Promise<{ ok: boolean; reason?: string }>
}
interface ExtensionContextLike {
  cwd?: unknown
  model?: { id?: unknown; name?: unknown; provider?: unknown }
  getContextUsage?: () => unknown
  sessionManager?: { getUsageStatistics?: () => unknown }
}

const AGENT_HOME_FALLBACK = path.join(os.homedir(), ".omp", "agent")
const TRACE_MODULE_REL = path.join("scripts", "harness-trace.mjs")

let traceModule: TraceModule | null = null
let traceId: string | null = null
let sessionId: string | null = null
let runId: string | null = null
 

function agentHome(): string {
  try {
    const meta: { url?: string } = import.meta as unknown as { url?: string }
    if (typeof meta.url === "string") {
      const home = path.dirname(path.dirname(fileURLToPath(meta.url)))
      if (home) return home
    }
  } catch {
    // extension runtime without import.meta - fall back to the default home
  }
  return AGENT_HOME_FALLBACK
}

async function ensureTraceModule(): Promise<TraceModule | null> {
  if (traceModule) return traceModule
  const candidates = [
    path.join(agentHome(), TRACE_MODULE_REL),
    path.join(AGENT_HOME_FALLBACK, TRACE_MODULE_REL),
  ]
  for (const file of candidates) {
    try {
      const loaded = (await import(pathToFileURL(file).href)) as unknown as TraceModule
      if (loaded && typeof loaded.appendEventAsync === "function" && typeof loaded.newId === "function") {
        traceModule = loaded
        return traceModule
      }
    } catch {
      // try the next candidate location
    }
  }
  return null
}

function modelFrom(context: ExtensionContextLike): { provider: string | null; name: string | null } | null {
  const model = context?.model
  if (!model || typeof model !== "object") return null
  const provider = typeof model.provider === "string" ? model.provider : null
  const name = typeof model.name === "string" ? model.name : typeof model.id === "string" ? model.id : null
  return provider || name ? { provider, name } : null
}

function finiteOrNull(value: unknown): number | null {
  return typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : null
}

function countersFrom(context: ExtensionContextLike): { usage?: unknown; cost?: unknown; context?: unknown } {
  const statsFn = context?.sessionManager?.getUsageStatistics
  const ctxFn = context?.getContextUsage
  const out: { usage?: unknown; cost?: unknown; context?: unknown } = {}
  if (typeof statsFn === "function" && context.sessionManager) {
    const stats = statsFn.call(context.sessionManager) as Record<string, unknown>
    if (stats && typeof stats === "object") {
      const input = finiteOrNull(stats.input)
      const output = finiteOrNull(stats.output)
      const total = finiteOrNull(stats.totalTokens)
      const usd = finiteOrNull(stats.cost)
      if (input !== null || output !== null || total !== null) {
        const usage: Record<string, unknown> = { available: true }
        if (input !== null) usage.input_tokens = input
        if (output !== null) usage.output_tokens = output
        if (total !== null) usage.total_tokens = total
        out.usage = usage
      }
      if (usd !== null) out.cost = { available: true, usd }
    }
  }
  if (typeof ctxFn === "function") {
    const ctx = ctxFn.call(context) as Record<string, unknown>
    if (ctx && typeof ctx === "object") {
      const windowTokens = finiteOrNull(ctx.contextWindow)
      const usedTokens = finiteOrNull(ctx.tokens)
      const percent = finiteOrNull(ctx.percent)
      if (windowTokens !== null || usedTokens !== null || percent !== null) {
        const contextRecord: Record<string, unknown> = { available: true }
        if (windowTokens !== null) contextRecord.window_tokens = windowTokens
        if (usedTokens !== null) contextRecord.used_tokens = usedTokens
        if (percent !== null) contextRecord.percent = percent
        out.context = contextRecord
      }
    }
  }
  return out
}

export function extractSkillSlugsFromPath(rawPath: unknown): string[] {
  if (typeof rawPath !== "string") return []
  const slugs: string[] = []
  const parts = rawPath.split(";")
  for (const part of parts) {
    const trimmed = part.trim()
    const match = trimmed.match(/^skill:\/\/([a-zA-Z0-9_-]+)/i)
    if (match) {
      const slug = match[1].toLowerCase()
      if (!slugs.includes(slug)) slugs.push(slug)
    }
  }
  return slugs
}

export function extractSkillSlugsFromToolInput(input: unknown): string[] {
  if (!input || typeof input !== "object") {
    return typeof input === "string" ? extractSkillSlugsFromPath(input) : []
  }
  const rec = input as Record<string, unknown>
  const candidates: unknown[] = [
    rec.path,
    rec.file_path,
    rec.filePath,
    rec.targetPath,
    rec.paths,
    rec.url,
    rec.uri,
  ]
  const slugs: string[] = []
  for (const candidate of candidates) {
    if (Array.isArray(candidate)) {
      for (const item of candidate) {
        for (const s of extractSkillSlugsFromPath(item)) {
          if (!slugs.includes(s)) slugs.push(s)
        }
      }
    } else if (typeof candidate === "string") {
      for (const s of extractSkillSlugsFromPath(candidate)) {
        if (!slugs.includes(s)) slugs.push(s)
      }
    }
  }
  return slugs
}

export function extractSkillSlugFromCommand(text: unknown): string | null {
  if (typeof text !== "string") return null
  const trimmed = text.trim()
  const match = trimmed.match(/^\/skill:([a-zA-Z0-9_-]+)/i)
  return match ? match[1].toLowerCase() : null
}

async function emitAsync(
  context: ExtensionContextLike,
  eventName: string,
  entityType: string,
  kind: string,
  parent: { type: string; id: string } | null,
  extra: Record<string, unknown>,
  entityId?: string,
): Promise<void> {
  const mod = traceModule
  if (!mod) return
  const cwd = typeof context?.cwd === "string" ? context.cwd : null
  if (!cwd) return
  if (!traceId) traceId = mod.newId("trc")
  if (!sessionId) sessionId = mod.newId("ses")
  const resolvedSession = sessionId
  const resolvedRun = runId ?? resolvedSession
  const resolvedEntity = entityId ?? (entityType === "session" ? resolvedSession : resolvedRun)
  const counters = entityType === "model" || kind === "end" ? countersFrom(context) : {}
  const envelope = {
    trace_id: traceId,
    run_id: resolvedRun,
    session_id: resolvedSession,
    entity: { type: entityType, id: resolvedEntity },
    parent,
    kind,
    model: modelFrom(context),
    usage: counters.usage,
    cost: counters.cost,
    context: counters.context,
    data: { native_event: eventName, ...extra },
  }
  const result = await mod.appendEventAsync(cwd, JSON.stringify(envelope))
  if (result && result.ok === false) {
    console.error("harness-omp-trace: append refused: " + String(result.reason ?? "unknown"))
  }
}
export default function registerHarnessOmpTrace(api: {
  on(event: string, handler: (event: unknown, context: ExtensionContextLike) => void | Promise<void>): void
}): void {
  api.on("session_start", async (event, context) => {
    const mod = await ensureTraceModule()
    if (!mod) return
    sessionId = mod.newId("ses")
    runId = mod.newId("run")
    await emitAsync(context, "session_start", "session", "start", null, {})
  })

  api.on("session_switch", async (_event, context) => {
    await emitAsync(context, "session_switch", "session", "record", null, {})
  })

  api.on("agent_start", async (event, context) => {
    const mod = await ensureTraceModule()
    if (!mod) return
    if (!sessionId) sessionId = mod.newId("ses")
    runId = mod.newId("run")
    await emitAsync(context, "agent_start", "run", "start", { type: "session", id: sessionId }, {})
  })

  api.on("tool_call", async (event, context) => {
    const mod = await ensureTraceModule()
    if (!mod) return
    const rec = typeof event === "object" && event !== null ? (event as Record<string, unknown>) : {}
    const input = rec.input ?? rec.args ?? rec.arguments ?? rec.parameters ?? event
    const slugs = extractSkillSlugsFromToolInput(input)
    for (const slug of slugs) {
      await emitAsync(
        context,
        "tool_call",
        "tool",
        "skill_loaded",
        runId ? { type: "run", id: runId } : (sessionId ? { type: "session", id: sessionId } : null),
        { slug, source: "read" },
        mod.newId("tool"),
      )
    }
  })

  api.on("input", async (event, context) => {
    const mod = await ensureTraceModule()
    if (!mod) return
    const text = typeof event === "string" ? event : (typeof (event as Record<string, unknown>)?.text === "string" ? (event as Record<string, unknown>).text : null)
    const slug = extractSkillSlugFromCommand(text)
    if (slug) {
      await emitAsync(
        context,
        "input",
        "tool",
        "skill_loaded",
        runId ? { type: "run", id: runId } : (sessionId ? { type: "session", id: sessionId } : null),
        { slug, source: "command" },
        mod.newId("tool"),
      )
    }
  })


  api.on("agent_end", async (event, context) => {
    const mod = await ensureTraceModule()
    if (!mod || !runId) return
    await emitAsync(context, "agent_end", "run", "end", { type: "session", id: sessionId ?? mod.newId("ses") }, {})
    await emitAsync(context, "model_record", "model", "record", { type: "run", id: runId }, {}, mod.newId("model"))
    runId = null
  })

  api.on("session_shutdown", async (_event, context) => {
    if (!traceModule || !sessionId) return
    await emitAsync(context, "session_shutdown", "session", "end", null, {})
    runId = null
  })
}

